export const appScript = "import { buildHealthReport } from '/health-model.js';\nconst state={company:{name:'美的集团',thscode:'000333.SZ'},bundle:null,range:60};\nconst $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[c]));\nconst num=v=>Number.isFinite(Number(v))?Number(v):null, fmt=(v,d=2)=>num(v)===null?'—':num(v).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d}), pct=v=>num(v)===null?'—':`${num(v)>=0?'+':''}${fmt(v,1)}%`, money=v=>num(v)===null?'—':num(v)>=1e8?`${fmt(num(v)/1e8,2)}亿`:`${fmt(num(v)/1e4,0)}万`;\nasync function api(path){const r=await fetch(path,{headers:{accept:'application/json'}}),b=await r.json().catch(()=>({error:{message:'服务器响应无法读取'}}));if(!r.ok)throw new Error(b.error?.message||`HTTP ${r.status}`);return b}\nasync function searchStocks(){const q=$('stock-search').value.trim();if(!q)return;const box=$('search-results');box.hidden=false;box.innerHTML='<div class=\"search-result\">正在查找…</div>';try{const result=await api(`/api/search?q=${encodeURIComponent(q)}`);if(result.items.length===1){const x=result.items[0];selectCompany(x.thscode,x.name||x.ticker);return}box.innerHTML=result.items.length?result.items.map(x=>`<button class=\"search-result\" data-code=\"${x.thscode}\" data-name=\"${esc(x.name||x.ticker)}\"><b>${esc(x.name||x.ticker)}</b><span>${x.thscode}</span></button>`).join(''):'<div class=\"search-result\">没有找到 A 股公司</div>'}catch(e){box.innerHTML=`<div class=\"search-result\">查找失败：${esc(e.message)}</div>`}}\nfunction loading(){const box=$('global-status');box.className='loading-box';box.innerHTML='<i></i><div><strong>正在生成体检报告</strong><p>同步核对行情、历史价格和财务报表…</p></div>';$('freshness').textContent='实时数据更新中'}\nasync function loadResearch(){loading();try{state.bundle=await api(`/api/research?thscode=${encodeURIComponent(state.company.thscode)}`);renderAll();const partial=Object.values(state.bundle.modules).some(x=>x.status!=='ok');$('global-status').className=`loading-box ${partial?'warning':'hidden'}`;if(partial)$('global-status').innerHTML='<div><strong>部分证据暂不可用</strong><p>已保留未知项，没有使用模拟数据补齐。</p></div>'}catch(e){$('global-status').className='loading-box error';$('global-status').innerHTML=`<div><strong>暂时无法生成体检</strong><p>${esc(e.message)}。没有用旧数据冒充最新结果。</p></div>`;$('freshness').textContent='数据连接失败'}}\nfunction renderHealthReport(){const report=buildHealthReport(state.bundle,state.company),m=state.bundle.modules.market,q=m.snapshot||{};$('company-name').textContent=state.company.name;$('company-code').textContent=state.company.thscode;$('company-avatar').textContent=state.company.name.slice(0,1);$('summary-text').textContent=report.summary;$('last-price').textContent=fmt(q.last_price);$('price-change').textContent=num(q.price_change_ratio_pct)===null?'实时快照缺失':`${q.price_change_ratio_pct>=0?'上涨':'下跌'} ${pct(q.price_change_ratio_pct)}`;$('return-60').textContent=pct(m.signals?.return60);$('drawdown-60').textContent=pct(m.signals?.maxDrawdown60);const countMap=[['positive','相对稳健'],['mixed','需要解释'],['negative','需要留意'],['unknown','仍待补充']];$('summary-counts').innerHTML=countMap.map(([key,label])=>`<div class=\"summary-count ${key}\"><b>${report.counts[key]||0}</b><span>${label}</span></div>`).join('');$('health-route').innerHTML=report.steps.map(step=>`<article class=\"health-step ${step.state}\"><div class=\"step-track\"><b>${step.number}</b><i></i></div><div class=\"step-body\"><header><div><span>${step.label}</span><h3>${step.question}</h3></div><button class=\"why-button\" aria-expanded=\"false\">为什么要看？</button></header><p class=\"why-copy\" hidden>${step.why}</p><h4>${step.conclusion}</h4><p>${step.interpretation}</p><div class=\"core-evidence\"><span>核心证据</span><b>${step.primaryEvidence}</b><button data-detail=\"${step.detailTarget}\">查看专业证据</button></div></div></article>`).join('');$('action-list').innerHTML=report.actions.map(x=>`<li>${esc(x)}</li>`).join('')}\nfunction chartPath(points,w,h,pad){if(!points.length)return '';const vals=points.map(p=>p.close_price),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;return points.map((p,i)=>`${i?'L':'M'}${pad+i*(w-2*pad)/Math.max(points.length-1,1)},${h-pad-(p.close_price-min)*(h-2*pad)/span}`).join(' ')}\nfunction renderPriceChart(){const m=state.bundle.modules.market,s=m.signals||{},points=(s.series||[]).slice(-state.range),svg=$('price-chart');if(!points.length){svg.innerHTML='<text x=\"450\" y=\"170\" text-anchor=\"middle\">价格历史暂不可用</text>';return}const w=900,h=340,p=42,path=chartPath(points,w,h,p),vals=points.map(x=>x.close_price),min=Math.min(...vals),max=Math.max(...vals),area=`${path} L${w-p},${h-p} L${p},${h-p} Z`;svg.innerHTML=`<defs><linearGradient id=\"fill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#176b56\" stop-opacity=\".22\"/><stop offset=\"1\" stop-color=\"#176b56\" stop-opacity=\"0\"/></linearGradient></defs>${[0,.5,1].map(t=>`<line x1=\"${p}\" x2=\"${w-p}\" y1=\"${p+t*(h-2*p)}\" y2=\"${p+t*(h-2*p)}\"/><text x=\"4\" y=\"${p+4+t*(h-2*p)}\">${fmt(max-t*(max-min),1)}</text>`).join('')}<path class=\"chart-area\" d=\"${area}\"/><path class=\"chart-line\" d=\"${path}\"/>`;$('market-metrics').innerHTML=[[`20 日平均价`,s.ma20,'观察短期趋势'],['60 日平均价',s.ma60,'观察中期趋势'],['120 日平均价',s.ma120,'观察较长期趋势'],['近 20 日平均成交额',money(s.averageTurnover20),'观察交易活跃度']].map(([a,b,c])=>`<div><span>${a}</span><b>${b??'—'}</b><small>${c}</small></div>`).join('')}\nconst period=r=>r?.period_end_ms||r?.period_end||r?.end_date_ms||null,pick=(r,keys)=>{for(const k of keys)if(r?.[k]!=null)return Number(r[k]);return null};\nconst indicatorNames={calculate_operating_income_yoy_growth_ratio:'营业收入同比增长',calculate_operating_profit_yoy_growth_ratio:'营业利润同比增长',total_assets_growth_ratio:'总资产增长',fixed_asset_invest_expansion_ratio:'固定资产投入扩张',calculate_parent_holder_net_profit_yoy_growth_ratio:'归母净利润同比增长',total_assets_net_ratio:'总资产净利率',index_deduct_weighted_avg_roe:'扣非净资产收益率',sale_gross_margin:'毛利率',sale_net_interest_ratio:'销售净利率',index_weighted_avg_roe:'净资产收益率',current_ratio:'流动比率',cash_ratio:'现金比率',quick_ratio:'速动比率',earned_interest_multiple:'利息保障倍数',assets_debt_ratio:'资产负债率',total_assets_turnover_ratio:'总资产周转率',inventory_turnover_ratio:'存货周转率',long_term_debt_equity_ratio:'长期负债与权益比',current_assets_turnover_ratio:'流动资产周转率',receive_account_turnover_ratio:'应收账款周转率',net_profit_cash_content:'每百元利润对应经营现金',cash_operating_index:'现金经营质量',operating_cash_flow_net_divide_income:'经营现金占收入比例',cash_meet_invest_ratio:'现金满足投资比例'};\nfunction renderFinancial(){const f=state.bundle.modules.financials,periods=[...new Set([...(f.income||[]),...(f.balance||[]),...(f.cashflow||[])].map(period).filter(Boolean))].sort((a,b)=>b-a).slice(0,8),at=(rows,p)=>(rows||[]).find(r=>period(r)===p)||{},rows=[['营业收入',p=>pick(at(f.income,p),['operating_income'])],['归母净利润',p=>pick(at(f.income,p),['parent_holder_net_profit'])],['经营现金流',p=>pick(at(f.cashflow,p),['act_cash_flow_net'])],['总资产',p=>pick(at(f.balance,p),['assets_total'])],['总负债',p=>pick(at(f.balance,p),['total_debt'])]];$('financial-table').innerHTML=periods.length?`<table><thead><tr><th>看什么</th>${periods.map(p=>`<th>${new Date(p).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit'})}</th>`).join('')}</tr></thead><tbody>${rows.map(([n,get])=>`<tr><td>${n}</td>${periods.map(p=>`<td>${money(get(p))}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p>财务表暂不可用。</p>';const abilities=state.bundle.modules.indicators.data?.abilities||[];$('indicator-groups').innerHTML=abilities.map(g=>`<article><h4>${({growth:'增长能力',profitability:'盈利能力',solvency:'偿债能力',operation:'经营效率','cash-flow':'现金质量'})[g.ability]||g.ability}</h4>${(g.indicators||[]).slice(0,5).map(i=>`<div><span>${indicatorNames[i.index_id]||'专业指标'}</span><b>${i.value??'—'}</b><small>${esc(i.index_id)}</small></div>`).join('')}</article>`).join('')}\nfunction renderLineage(){const names={market:'行情与历史价格',financials:'三张财务报表',indicators:'财务指标'};$('lineage-grid').innerHTML=Object.entries(state.bundle.modules).map(([k,m])=>`<article><header><h4>${names[k]}</h4><span class=\"${m.status}\">${m.status==='ok'?'已取得':'不完整'}</span></header><p>来源：同花顺扶摇金融数据 API</p><details><summary>查看请求编号</summary>${(m.requestIds||[]).map(id=>`<code>${esc(id)}</code>`).join('')||'<span>暂无成功请求</span>'}</details></article>`).join('')}\nfunction renderProfessionalEvidence(){renderPriceChart();renderFinancial();renderLineage()}\nfunction renderAll(){renderHealthReport();renderProfessionalEvidence();const report=buildHealthReport(state.bundle,state.company);$('freshness').textContent=`行情更新于 ${new Date(state.bundle.generatedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})} · 财务截至 ${report.financialPeriod||'未知报告期'}`}\nfunction selectCompany(code,name){state.company={thscode:code,name:name||code};$('stock-search').value=state.company.name;$('search-results').hidden=true;loadResearch()}\n$('search-button').addEventListener('click',searchStocks);$('stock-search').addEventListener('keydown',e=>{if(e.key==='Enter')searchStocks()});$('search-results').addEventListener('click',e=>{const b=e.target.closest('[data-code]');if(b)selectCompany(b.dataset.code,b.dataset.name)});document.querySelectorAll('.quick-stocks button').forEach(b=>b.addEventListener('click',()=>selectCompany(b.dataset.code,b.dataset.name)));$('refresh-button').addEventListener('click',loadResearch);\n$('health-route').addEventListener('click',e=>{const why=e.target.closest('.why-button');if(why){const copy=why.closest('.step-body').querySelector('.why-copy'),open=copy.hidden;copy.hidden=!open;why.setAttribute('aria-expanded',String(open));why.textContent=open?'收起解释':'为什么要看？'}const detail=e.target.closest('[data-detail]');if(detail){$('professional-evidence').open=true;document.querySelector(`[data-panel=\"${detail.dataset.detail}\"]`)?.click();$('professional-evidence').scrollIntoView({behavior:'smooth'})}});\ndocument.querySelector('.evidence-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-panel]');if(!b)return;document.querySelectorAll('.evidence-tabs button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.evidence-panel').forEach(x=>x.classList.toggle('active',x.id===`${b.dataset.panel}-panel`))});document.querySelector('.range-switch').addEventListener('click',e=>{const b=e.target.closest('[data-range]');if(!b)return;state.range=Number(b.dataset.range);document.querySelectorAll('.range-switch button').forEach(x=>x.classList.toggle('active',x===b));renderPriceChart()});\nfunction drawer(id,open){$(id).classList.toggle('open',open);$(id).setAttribute('aria-hidden',String(!open));document.body.style.overflow=open?'hidden':''}$('method-button').addEventListener('click',()=>drawer('method-modal',true));document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>drawer(b.closest('.drawer').id,false)));loadResearch();\n";
export const healthModelScript = "const STATUS = {\n  positive: '表现较稳',\n  negative: '需要留意',\n  mixed: '出现分化',\n  unknown: '暂无结论',\n};\n\nconst number = value => value === null || value === undefined || value === '--' || !Number.isFinite(Number(value)) ? null : Number(value);\nconst pct = value => number(value) === null ? '—' : `${number(value) >= 0 ? '+' : ''}${number(value).toFixed(1)}%`;\n\nfunction indicators(bundle) {\n  const abilities = bundle?.modules?.indicators?.data?.abilities || [];\n  return Object.fromEntries(abilities.flatMap(group => (group.indicators || []).map(item => [item.index_id, number(item.value)])));\n}\n\nfunction metric(map, names) {\n  for (const name of names) if (map[name] !== undefined) return map[name];\n  return null;\n}\n\nfunction step({ key, number, question, why, state, conclusion, interpretation, primaryEvidence, detailTarget }) {\n  return { key, number, question, why, state, label: STATUS[state], conclusion, interpretation, primaryEvidence, detailTarget };\n}\n\nexport function buildHealthReport(bundle, company) {\n  const modules = bundle?.modules || {};\n  const values = indicators(bundle);\n  const revenue = metric(values, ['calculate_operating_income_yoy_growth_ratio', 'operating_income_yoy_growth_ratio']);\n  const profit = metric(values, ['calculate_parent_holder_net_profit_yoy_growth_ratio', 'net_profit_yoy_growth_ratio']);\n  const cash = metric(values, ['net_profit_cash_content']);\n  const debt = metric(values, ['assets_debt_ratio']);\n  const market = modules.market || {};\n  const return60 = number(market.signals?.return60);\n  const drawdown = number(market.signals?.maxDrawdown60);\n\n  const growthState = revenue === null || profit === null ? 'unknown' : revenue >= 0 && profit >= 0 ? 'positive' : revenue * profit < 0 ? 'mixed' : 'negative';\n  const cashState = cash === null ? 'unknown' : cash >= 100 ? 'positive' : cash >= 60 ? 'mixed' : 'negative';\n  const debtState = debt === null ? 'unknown' : debt <= 60 ? 'positive' : debt <= 70 ? 'mixed' : 'negative';\n  const marketState = return60 === null || drawdown === null ? 'unknown' : return60 >= 0 && drawdown > -15 ? 'positive' : return60 < 0 ? 'negative' : 'mixed';\n\n  const steps = [\n    step({ key: 'earning', number: '01', question: '生意还在增长吗？', why: '收入说明生意规模，利润说明增长有没有真正留下来；两者要一起看。', state: growthState, conclusion: growthState === 'unknown' ? '关键增长数据还不完整' : growthState === 'positive' ? '收入和利润仍在同向增长' : growthState === 'mixed' ? '收入与利润的方向出现分化' : '收入和利润都面临增长压力', interpretation: growthState === 'positive' ? '增长方向一致，但还需继续观察增速是否放缓。' : growthState === 'mixed' ? '只看收入或利润都会失真，需要检查成本、毛利和一次性项目。' : growthState === 'negative' ? '当前增长承压，不代表未来一定继续下降。' : '没有足够证据时，不用旧数据代替最新判断。', primaryEvidence: `收入同比 ${pct(revenue)} · 归母净利润同比 ${pct(profit)}`, detailTarget: 'financial' }),\n    step({ key: 'cash', number: '02', question: '赚到的钱真的收到现金了吗？', why: '利润是会计结果，现金是实际流入；现金跟不上时，利润质量可能需要进一步核实。', state: cashState, conclusion: cash === null ? '暂时无法判断利润的现金含量' : cashState === 'positive' ? '经营现金能够较好覆盖利润' : cashState === 'mixed' ? '利润和现金基本匹配，但不算充裕' : '利润转成现金的能力偏弱', interpretation: cashState === 'positive' ? '每 100 元利润对应的经营现金不少于 100 元，现金质量相对扎实。' : cashState === 'unknown' ? '需要经营现金流与净利润的同口径数据。' : '需要继续检查应收账款、存货和付款节奏。', primaryEvidence: `每 100 元利润对应经营现金 ${cash === null ? '—' : cash.toFixed(0) + ' 元'}`, detailTarget: 'financial' }),\n    step({ key: 'safety', number: '03', question: '公司的财务负担重吗？', why: '负债不是越少越好，但过高会降低公司应对行业波动的余地。', state: debtState, conclusion: debt === null ? '暂时无法判断负债水平' : debtState === 'positive' ? '整体负债水平相对温和' : debtState === 'mixed' ? '负债水平需要结合行业理解' : '负债水平偏高，需要重点核实', interpretation: debtState === 'mixed' ? '制造业常有经营性负债，不能只凭一个比例判定风险。' : debtState === 'positive' ? '当前比例留有一定缓冲，但仍要看短期偿债和利息压力。' : debtState === 'negative' ? '需要进一步区分有息负债与经营性负债。' : '缺失时保持未知，不用行业印象代替数据。', primaryEvidence: `每 100 元资产中负债 ${debt === null ? '—' : debt.toFixed(1) + ' 元'}`, detailTarget: 'financial' }),\n    step({ key: 'market', number: '04', question: '市场最近怎么看它？', why: '价格反映市场近期态度，不等于公司价值；趋势和回撤要放在一起看。', state: marketState, conclusion: return60 === null ? '近期市场数据暂不可用' : marketState === 'positive' ? '近期价格表现相对平稳' : marketState === 'negative' ? '近期价格表现偏弱' : '价格有表现，但波动也较明显', interpretation: '这是历史市场表现，不是未来涨跌预测；请和基本面变化对照阅读。', primaryEvidence: `近 60 日 ${pct(return60)} · 最大回撤 ${pct(drawdown)}`, detailTarget: 'market' }),\n    step({ key: 'unknowns', number: '05', question: '还有哪些事现在不能下结论？', why: '好的研究不仅说知道什么，也要明确哪些关键证据仍然缺失。', state: 'unknown', conclusion: '估值、同行位置和最新事件仍待补充', interpretation: '没有同日估值、可比公司分位和公告原文时，不判断“贵不贵”或事件影响。', primaryEvidence: '3 类关键证据尚未接入', detailTarget: 'lineage' }),\n  ];\n\n  const counts = steps.reduce((acc, item) => ({ ...acc, [item.state]: (acc[item.state] || 0) + 1 }), {});\n  const incomplete = [modules.market, modules.financials, modules.indicators].some(module => !module || module.status !== 'ok');\n  const attention = steps.filter(item => item.state === 'negative' || item.state === 'mixed');\n  const vitalUnknowns = steps.slice(0, 4).filter(item => item.state === 'unknown').length;\n  const financialDates = [...(modules.financials?.income || []), ...(modules.financials?.balance || []), ...(modules.financials?.cashflow || [])]\n    .map(row => row?.period_end_ms || row?.period_end || row?.end_date_ms).filter(Boolean).map(Number).filter(Number.isFinite);\n  const financialPeriod = financialDates.length ? new Date(Math.max(...financialDates)).toISOString().slice(0, 10) : null;\n  const summary = vitalUnknowns >= 2\n    ? `${company.name} 目前不足以概括基本面，先补齐关键体征再判断。`\n    : incomplete\n    ? `${company.name} 的证据还不完整，先看已确认部分，再补齐缺失数据。`\n    : attention.length\n      ? `${company.name} 的基本面有支撑，但有 ${attention.length} 项值得继续核实。`\n      : `${company.name} 当前几项核心体征较平稳，但仍有未知信息需要补充。`;\n  const actions = [\n    ...(incomplete ? ['补齐未成功返回的数据模块，再更新体检结论。'] : []),\n    ...attention.slice(0, 2).map(item => `继续核实「${item.question.replace('？', '')}」背后的变化原因。`),\n    '补充同行估值和最新公告后，再形成更完整判断。',\n  ].slice(0, 3);\n\n  return { company, summary, counts, steps, actions, financialPeriod };\n}\n";
